// Process Workflow 4 orders
// Fetch 3-manifest from R2 and include in payload (W4 needs pages data)
// Defensive: Handle various input structures
const input = $input.first();
if (!input || !input.json) {
  console.log('No input for Workflow 4');
  return [];
}

const routing = input.json;
if (!routing || typeof routing !== 'object') {
  console.log('Invalid routing structure for Workflow 4');
  return [];
}

const orders4 = Array.isArray(routing.workflow4) ? routing.workflow4 : [];

if (orders4.length === 0) {
  console.log('No orders for Workflow 4');
  return [];
}

console.log(`=== PROCESSING ${orders4.length} ORDERS FOR WORKFLOW 4 ===`);

const prefix = 'book-mvp-simple-adventure/orders';
const supabaseUrl = 'https://mdnthwpcnphjnnblbvxk.supabase.co';
const supabaseKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im1kbnRod3BjbnBoam5uYmxidnhrIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2MDUwMDc4MCwiZXhwIjoyMDc2MDc2NzgwfQ.wNVQ3U2nWTGu8VsuXKasWOCxVhpca5x42wSapQDinGs';

// R2 public URL for fetching manifests
const publicR2Url = 'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev';

const processed = [];
const skipped = [];

for (const order of orders4) {
  const orderId = order.amazon_order_id;

  // Construct 3-manifest path (W4 needs the 3-manifest with pages data)
  const manifest3Key = `${prefix}/${orderId}/manifests/3-manifest.json`;
  const manifest3Url = `${publicR2Url}/${manifest3Key}`;

  // Fetch 3-manifest from R2
  let manifest3 = null;
  try {
    console.log(`Fetching 3-manifest from: ${manifest3Url}`);
    const response = await fetch(manifest3Url);
    if (response.ok) {
      manifest3 = await response.json();
      console.log(`✅ Fetched 3-manifest for order ${orderId}`);
    } else {
      console.warn(`⚠️ Failed to fetch 3-manifest (${response.status}) for order ${orderId}`);
    }
  } catch (error) {
    console.error(`❌ Error fetching 3-manifest for order ${orderId}:`, error.message);
  }

  // If manifest3 is missing, mark order as error
  if (!manifest3) {
    console.warn(`⚠️ Order ${orderId} missing 3-manifest.json - marking as error`);

    try {
      await fetch(
        `${supabaseUrl}/rest/v1/orders?id=eq.${order.id}`,
        {
          method: 'PATCH',
          headers: {
            'apikey': supabaseKey,
            'Authorization': `Bearer ${supabaseKey}`,
            'Content-Type': 'application/json',
            'Prefer': 'return=representation'
          },
          body: JSON.stringify({
            execution_status: 'error',
            error_type: 'missing_manifest',
            error_message: 'Missing required 3-manifest.json file for Workflow 4',
            updated_at: new Date().toISOString()
          })
        }
      );
    } catch (error) {
      console.error(`Failed to mark order ${orderId} as error:`, error);
    }

    skipped.push(orderId);
    continue;
  }

  // Include manifest3 data in payload (pages, pngGeneration, etc.)
  processed.push({
    json: {
      orderId: orderId,
      characterHash: order.character_hash,
      orderDbId: order.id,
      workflow: '4',
      // Include 3-manifest data for W4 validation
      ...manifest3,  // Spread manifest3 to include pages, pngGeneration, etc.
      // Also include oneManifestKey for reference (W4 may need it)
      oneManifestKey: order.one_manifest_url || `${prefix}/${orderId}/manifests/1-manifest.json`
    }
  });
}

if (skipped.length > 0) {
  console.log(`⚠️ Skipped ${skipped.length} orders due to missing 3-manifest: ${skipped.join(', ')}`);
}

console.log(`✅ Processed ${processed.length} orders for Workflow 4`);

return processed;

// Merge Prep Data with Supabase Response (3)
// Combines original prep data (dedicationText, oneManifestKey, etc.) with Supabase response

const supabaseResponse = $input.first().json || {};
const isArray = Array.isArray(supabaseResponse);
const supabaseData = isArray ? (supabaseResponse.length > 0 ? supabaseResponse[0] : {}) : supabaseResponse;

// Retrieve original prep data from Prep Workflow 3 Orders node
let prepData = {};
try {
  const prepItems = $items('Prep Workflow 3 Orders', 0, $runIndex);
  if (prepItems && prepItems.length > 0) {
    // Find the matching item by orderDbId
    const matchingPrep = prepItems.find(item => 
      item.json.orderDbId === supabaseData.id || 
      item.json.orderDbId === supabaseData.orderDbId
    ) || prepItems[0]; // Fallback to first item if no match
    prepData = matchingPrep.json || {};
  }
} catch (error) {
  console.warn('Could not retrieve prep data:', error.message);
}

// Merge prep data with Supabase response
// Prefer prep data for fields like dedicationText, oneManifestKey, etc.
// Use Supabase data for database fields like id, started_at, etc.
const merged = {
  ...prepData, // Original prep data (dedicationText, oneManifestKey, orderId, characterHash, workflow)
  ...supabaseData, // Supabase response (id, started_at, execution_status, current_workflow)
  // Ensure critical fields are preserved
  orderId: prepData.orderId || supabaseData.amazon_order_id || supabaseData.amazonOrderId,
  oneManifestKey: prepData.oneManifestKey, // Only in prep data
  dedicationText: prepData.dedicationText, // Only in prep data
  characterHash: prepData.characterHash || supabaseData.character_hash,
  workflow: prepData.workflow || supabaseData.current_workflow || '3',
  orderDbId: supabaseData.id || prepData.orderDbId,
  claimedAt: supabaseData.started_at
};

return [{ json: merged }];

// Process Workflow 3 orders
const routing = $input.first().json;
const orders3 = routing.workflow3 || [];

if (orders3.length === 0) {
  console.log('No orders for Workflow 3');
  return [];
}

console.log(`=== PROCESSING ${orders3.length} ORDERS FOR WORKFLOW 3 ===`);

const prefix = 'book-mvp-simple-adventure/orders';
const supabaseUrl = 'https://mdnthwpcnphjnnblbvxk.supabase.co';
const supabaseKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im1kbnRod3BjbnBoam5uYmxidnhrIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2MDUwMDc4MCwiZXhwIjoyMDc2MDc2NzgwfQ.wNVQ3U2nWTGu8VsuXKasWOCxVhpca5x42wSapQDinGs';

const processed = [];
const skipped = [];

for (const order of orders3) {
  // Check if one_manifest_url exists
  const manifestUrl = order.one_manifest_url || order.oneManifestUrl;

  if (!manifestUrl) {
    console.warn(`⚠️ Order ${order.amazon_order_id} missing 1-manifest.json - marking as error`);

    // Mark order as error in Supabase
    try {
      await fetch(
        `${supabaseUrl}/rest/v1/orders?id=eq.${order.id}`,
        {
          method: 'PATCH',
          headers: {
            'apikey': supabaseKey,
            'Authorization': `Bearer ${supabaseKey}`,
            'Content-Type': 'application/json',
            'Prefer': 'return=representation'
          },
          body: JSON.stringify({
            execution_status: 'error',
            error_type: 'missing_manifest',
            error_message: 'Missing required 1-manifest.json file for Workflow 3',
            updated_at: new Date().toISOString()
          })
        }
      );
    } catch (error) {
      console.error(`Failed to mark order ${order.amazon_order_id} as error:`, error);
    }

    skipped.push(order.amazon_order_id);
    continue;
  }

  // Use manifest URL from database, or construct from prefix if it's just a key
  const oneManifestKey = manifestUrl.startsWith('http') ? manifestUrl : manifestUrl;
  const finalKey = manifestUrl.includes('/manifests/1-manifest.json') ? manifestUrl : `${prefix}/${order.amazon_order_id}/manifests/1-manifest.json`;

  processed.push({
    json: {
      orderId: order.amazon_order_id,
      oneManifestKey: finalKey,
      characterHash: order.character_hash,
      orderDbId: order.id,
      workflow: '3',
      dedicationText: order.dedication_text || null
    }
  });
}

if (skipped.length > 0) {
  console.log(`⚠️ Skipped ${skipped.length} orders due to missing manifest: ${skipped.join(', ')}`);
}

console.log(`✅ Processed ${processed.length} orders for Workflow 3`);

return processed;

// Process 2B orders
const routing = $input.first().json;
const orders2B = routing.workflow2B || [];

if (orders2B.length === 0) {
  console.log('No orders for 2B');
  return [];
}

console.log(`=== PROCESSING ${orders2B.length} ORDERS FOR 2B ===`);

// Keep payload minimal; W2B will pull any needed URLs or keys itself
return orders2B.map(order => ({
  json: {
    orderId: order.amazon_order_id,
    characterHash: order.character_hash,
    orderDbId: order.id,
    workflow: '2B'
  }
}));

// Process 2A orders
// If character_specs is null, fetch from manifest
const routing = $input.first().json;
const orders2A = routing.workflow2A || [];

if (orders2A.length === 0) {
  console.log('No orders for 2A');
  return [];
}

console.log(`=== PROCESSING ${orders2A.length} ORDERS FOR 2A ===`);

// Process each order
const processed = [];
for (const order of orders2A) {
  let characterSpecs = order.character_specs;
  let bookSpecs = order.book_specs;
  let characterHash = order.character_hash;

  // If character_specs is null but we have a manifest URL, fetch it
  if (!characterSpecs && order.one_manifest_url) {
    try {
      const manifestKey = order.one_manifest_url;
      const publicR2Url = 'https://pub-92cec53654f84771956bc84dfea65baa.r2.dev';
      const manifestUrl = `${publicR2Url}/${manifestKey}`;

      console.log(`Fetching manifest from: ${manifestUrl}`);

      const response = await fetch(manifestUrl);
      if (response.ok) {
        const manifest = await response.json();

        // Extract character specs and book specs from manifest
        if (manifest.order) {
          characterSpecs = manifest.order.characterSpecs || null;
          bookSpecs = manifest.order.bookSpecs || null;

          // Generate character hash if we have character specs but no hash
          if (characterSpecs && !characterHash && characterSpecs.childName) {
            // Simple hash generation (n8n code nodes don't have require())
            const hashInput = `${characterSpecs.childName}-${characterSpecs.skinTone}-${characterSpecs.hairColor}-${characterSpecs.hairStyle}`;
            // Simple hash: convert string to number, then to hex
            let hash = 0;
            for (let i = 0; i < hashInput.length; i++) {
              const char = hashInput.charCodeAt(i);
              hash = ((hash << 5) - hash) + char;
              hash = hash & hash; // Convert to 32-bit integer
            }
            characterHash = Math.abs(hash).toString(16).slice(0, 8);
            console.log(`Generated character hash: ${characterHash}`);
          }

          console.log(`✅ Extracted character specs from manifest for order ${order.amazon_order_id}`);
        } else {
          console.warn(`⚠️ Manifest missing 'order' field for ${order.amazon_order_id}`);
        }
      } else {
        console.warn(`⚠️ Failed to fetch manifest (${response.status}) for ${order.amazon_order_id}`);
      }
    } catch (error) {
      console.error(`❌ Error fetching manifest for ${order.amazon_order_id}:`, error.message);
      // Continue with null values - 2A will need to handle this
    }
  }

  processed.push({
    json: {
      orderId: order.amazon_order_id,
      characterHash: characterHash,
      characterSpecs: characterSpecs,
      bookSpecs: bookSpecs,
      orderDbId: order.id,
      workflow: '2A',
      // Pass through manifest URL for reference
      oneManifestUrl: order.one_manifest_url || null
    }
  });
}

return processed;

// Reset capacity counter when we have capacity
if ($execution.customData) {
  $execution.customData.capacityFullCycles = 0;
}

// Route order to correct workflow based on next_workflow field
const orders = $input.all();

if (!orders || orders.length === 0) {
  console.log('No orders to route');
  return [];
}

const routed = {
  workflow2A: [],
  workflow2B: [],
  workflow3: [],
  workflow4: []
};

for (const item of orders) {
  const order = item.json;
  const nextWorkflow = order.next_workflow;

  console.log(`Order ${order.amazon_order_id}: Route to ${nextWorkflow}`);

  if (nextWorkflow === '2A') {
    routed.workflow2A.push(order);
  } else if (nextWorkflow === '2B') {
    routed.workflow2B.push(order);
  } else if (nextWorkflow === '3') {
    routed.workflow3.push(order);
  } else if (nextWorkflow === '4') {
    routed.workflow4.push(order);
  } else {
    console.warn(`⚠️ Unknown workflow: ${nextWorkflow} for order ${order.amazon_order_id}`);
  }
}

console.log(`Routing summary:`);
console.log(`  2A: ${routed.workflow2A.length} orders`);
console.log(`  2B: ${routed.workflow2B.length} orders`);
console.log(`  3: ${routed.workflow3.length} orders`);
console.log(`  4: ${routed.workflow4.length} orders`);

return [{ json: routed }];

// Extract orders from Vercel Cron webhook payload
// n8n webhook structure: { body: { orders: [...] }, headers: {...}, params: {...}, query: {...} }
// Vercel sends: { orders: [...] } in the body
// This node extracts the orders array from body and passes through
const webhookData = $input.first().json || {};

// Check body.orders first (n8n webhook structure), then fallback to top-level orders
const orders = webhookData.body?.orders || webhookData.orders || [];

console.log('=== ROUTER WEBHOOK TRIGGERED ===');
console.log('Webhook data keys:', Object.keys(webhookData));
console.log('Has body:', !!webhookData.body);
console.log('Body keys:', webhookData.body ? Object.keys(webhookData.body) : 'N/A');
console.log(`Received ${orders.length} orders from Vercel Cron`);

if (orders.length === 0) {
  console.log('No orders in webhook payload - workflow will stop');
  console.log('Webhook data structure:', JSON.stringify(webhookData, null, 2).substring(0, 500));
  return [];
}

// Return orders as individual items for routing
return orders.map(order => ({ json: order }));

// Verify Order Claimed (2B)
// Check if the PATCH succeeded - if empty array, order was already claimed

const markResult = $input.first().json || {};
const isArray = Array.isArray(markResult);
const hasData = isArray ? markResult.length > 0 : (markResult && Object.keys(markResult).length > 0);

if (!hasData) {
  console.log('⚠️ Order already claimed by another router cycle - skipping trigger');
  return []; // Empty output stops execution
}

console.log('✅ Order successfully claimed - proceeding to trigger');
const orderData = isArray ? markResult[0] : markResult;

// Pass through original routing data
const prepData = $('Prep 2B Orders').first().json;
return [{
  json: {
    ...prepData,
    orderDbId: orderData.id || prepData.orderDbId,
    claimedAt: orderData.started_at
  }
}];

// Verify Order Claimed (3)
// Check if the PATCH succeeded - if empty array, order was already claimed
// Input comes from Merge Prep Data node which combines prep data with Supabase response

const merged = $input.first().json || {};
const isArray = Array.isArray(merged);

// CRITICAL: Check if Supabase PATCH actually succeeded
// If Supabase returned empty array, the order was already claimed
// The merge node combines prep data with Supabase response, so we need to check
// if the Supabase response has an 'id' field (which indicates successful PATCH)
const supabaseSucceeded = merged.id || (isArray && merged.length > 0 && merged[0]?.id);

if (!supabaseSucceeded) {
  console.log('⚠️ Order already claimed by another router cycle - Supabase PATCH returned no data');
  return []; // Empty output stops execution
}

// Now check if we have valid merged data
const hasData = isArray ? merged.length > 0 : (merged && Object.keys(merged).length > 0);
if (!hasData) {
  console.log('⚠️ No data after merge - skipping trigger');
  return [];
}

console.log('✅ Order successfully claimed - proceeding to trigger');
const orderData = isArray ? merged[0] : merged;

// Extract prep data from merged result (already merged by previous node)
// The merged data has all prep fields (orderId, dedicationText, etc.) plus processing status
const prepData = {
  orderId: orderData.orderId || orderData.amazon_order_id || orderData.amazonOrderId,
  oneManifestKey: orderData.oneManifestKey,
  characterHash: orderData.characterHash || orderData.character_hash,
  orderDbId: orderData.id || orderData.orderDbId,
  workflow: orderData.workflow || '3',
  dedicationText: orderData.dedicationText || orderData.dedication_text || null,
  claimedAt: orderData.started_at || orderData.claimedAt
};

return [{
  json: prepData
}];

// Verify Order Claimed (4)
// Check if the PATCH succeeded - if empty array, order was already claimed

const markResult = $input.first().json || {};
const isArray = Array.isArray(markResult);
const hasData = isArray ? markResult.length > 0 : (markResult && Object.keys(markResult).length > 0);

if (!hasData) {
  console.log('⚠️ Order already claimed by another router cycle - skipping trigger');
  return []; // Empty output stops execution
}

console.log('✅ Order successfully claimed - proceeding to trigger');
const orderData = isArray ? markResult[0] : markResult;

// Pass through original routing data
const prepData = $('Prep Workflow 4 Orders').first().json;
return [{
  json: {
    ...prepData,
    orderDbId: orderData.id || prepData.orderDbId,
    claimedAt: orderData.started_at,
    oneManifestUrl: prepData.oneManifestUrl || prepData.oneManifestKey
  }
}];

// Fetch a signed GET URL for oneManifestKey via backend
// NOTE: n8n Cloud doesn't allow env var access in Code nodes, so using hardcoded token
// IMPORTANT: This token must match BACKEND_API_TOKEN in Vercel environment variables
const item = $input.first().json;
const endpoint = 'https://admin.littleherolabs.com/api/r2/signed-url';
// Backend API token for authentication (from W0 config)
// Update this if BACKEND_API_TOKEN changes in Vercel
const token = 'e41d510ce6ed6e9c7f602fea860f2591cc7ec75fe63e448336a97c4b73898646';
const ttl = 600;

if (!item.oneManifestKey) {
  throw new Error('Missing oneManifestKey');
}

if (!token || token.trim() === '') {
  throw new Error('BACKEND_API_TOKEN not configured. Token is required for authentication.');
}

console.log(`[Get Signed URL] Requesting signed URL for: ${item.oneManifestKey}`);
console.log(`[Get Signed URL] Endpoint: ${endpoint}`);
console.log(`[Get Signed URL] Token present: ${!!token} (length: ${token.length})`);

try {
  const res = await this.helpers.request({
    method: 'GET',
    uri: endpoint,
    qs: { key: item.oneManifestKey, bucket: 'little-hero-orders', expiresIn: ttl },
    headers: { 
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json'
    },
    json: true
  });

  console.log(`[Get Signed URL] Response received:`, {
    hasUrl: !!res.url,
    hasData: !!res.data,
    hasJson: !!res.json,
    hasResult: !!res.result,
    responseKeys: Object.keys(res || {})
  });

  const oneManifestUrl = res.url || res.data?.url || res.json?.url || res.result?.url;

  if (!oneManifestUrl) {
    console.error('[Get Signed URL] Response structure:', JSON.stringify(res, null, 2).substring(0, 500));
    throw new Error('Signed URL endpoint did not return a URL. Check response structure above.');
  }

  console.log(`[Get Signed URL] ✅ Successfully obtained signed URL (length: ${oneManifestUrl.length})`);
  return [{ json: { ...item, oneManifestUrl } }];
} catch (error) {
  console.error('[Get Signed URL] Request failed:', {
    message: error.message,
    status: error.response?.status,
    statusText: error.response?.statusText,
    data: error.response?.data
  });

  if (error.response?.status === 401) {
    throw new Error('Authentication failed (401). Check that BACKEND_API_TOKEN in n8n matches the token in Vercel environment variables.');
  }

  throw error;
}
